//! 🧪️ The canonical Emit golden wire is independent of borrowed slice width and rejects foreign fields before writing.
use super::*;
#[test]
fn original_emit_frame_borrowed_wire_matches_canonical_channel(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let fields:Vec<Vec<u8>>=law["fields"].as_array().unwrap().iter().map(|row|row.as_array().unwrap().iter().map(|byte|byte.as_u64().unwrap()as u8).collect()).collect();let expected=law["expectedHex"].as_str().unwrap();let view=AppEmitFrameView{in_reply_to:u64::MAX,document_ops:&fields[0],config_ops:&fields[1],draft_ops:&fields[2],output:&fields[3],diagnostics:&fields[4],child_ops:&fields[5]};let reference=super::super::AppFrame::Emit{in_reply_to:u64::MAX,document_ops:fields[0].clone(),config_ops:fields[1].clone(),draft_ops:fields[2].clone(),output:fields[3].clone(),diagnostics:fields[4].clone(),child_ops:fields[5].clone()};let reference=semio_framework_async::poll::resolve_ready(crate::encode_app_frame(&reference));for width in law["fragmentSizes"].as_array().unwrap(){let mut cursor=AppEmitFrameWireCursor::default();let mut actual=Vec::new();let mut output=vec![0;width.as_u64().unwrap()as usize];for index in 0..10000{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.write(&view,91,&mut output).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));actual.extend_from_slice(&output[..step.written_bytes]);assert!(step.written_bytes<=64);if step.complete{break}assert!(index<9999);}assert_eq!(actual,reference);assert_eq!(actual.iter().map(|byte|format!("{byte:02x}")).collect::<String>(),expected);let mut scratch=[0xa5;64];assert!(cursor.write(&view,92,&mut scratch).is_err());assert_eq!(scratch,[0xa5;64]);let foreign=fields[3].clone();let changed=AppEmitFrameView{output:&foreign,..view};assert!(cursor.write(&changed,91,&mut scratch).is_err());assert_eq!(scratch,[0xa5;64]);cursor.close();assert!(cursor.terminal_is_empty());assert!(cursor.write(&view,91,&mut scratch).is_err());}}

#[test]
fn original_emit_frame_wide_source_cancellation_keeps_only_borrowed_originals(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let mut fields:Vec<Vec<u8>>=law["fields"].as_array().unwrap().iter().map(|row|row.as_array().unwrap().iter().map(|byte|byte.as_u64().unwrap()as u8).collect()).collect();fields[3]=vec![law["wide"]["byte"].as_u64().unwrap()as u8;law["wide"]["length"].as_u64().unwrap()as usize];let pointers:Vec<_>=fields.iter().map(|field|field.as_ptr()).collect();for width in [1,7,64,4096]{for cut in law["cancelAfter"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize)).chain([None]){let view=AppEmitFrameView{in_reply_to:u64::MAX,document_ops:&fields[0],config_ops:&fields[1],draft_ops:&fields[2],output:&fields[3],diagnostics:&fields[4],child_ops:&fields[5]};let mut cursor=AppEmitFrameWireCursor::default();let mut output=vec![0;width];let mut actual=Vec::new();for index in 0..20000{if cut==Some(index){break}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.write(&view,91,&mut output).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));actual.extend_from_slice(&output[..step.written_bytes]);if step.complete{break}assert!(index<19999);}if cut.is_none(){assert!(cursor.is_complete());let frame=super::super::AppFrame::Emit{in_reply_to:u64::MAX,document_ops:fields[0].clone(),config_ops:fields[1].clone(),draft_ops:fields[2].clone(),output:fields[3].clone(),diagnostics:fields[4].clone(),child_ops:fields[5].clone()};assert_eq!(actual,semio_framework_async::poll::resolve_ready(crate::encode_app_frame(&frame)));}let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(cursor.terminal_is_empty());assert_eq!(fields.iter().map(|field|field.as_ptr()).collect::<Vec<_>>(),pointers);}}}
